import{j as e}from"./index-B4Co0jQl.js";import{S as t,s as a}from"./ServicePage-BQcD3yzJ.js";import"./Breadcrumbs-C03JGUn9.js";import"./triangle-alert-CorMmclv.js";const n={path:"/services/machine-learning-development",icon:"machine-learning",h1:"Machine Learning Development",valueProp:"Models trained on the data your business already produces — to predict, classify, recommend or flag — and then integrated somewhere a person will actually see the result.",heroHighlights:["Prediction, classification, recommendation and anomaly detection","Feasibility judged on your data before any model is proposed","Evaluation and monitoring after launch, not just at handover"],intro:['Machine learning is a different discipline from the generative AI most people now mean by "AI". It does not write prose. It learns patterns from historical examples and applies them to new ones: which customers are likely to churn, which transactions look unlike the rest, which of forty document types this scan is, which three products this shopper is most likely to want.',"That makes the constraint different too. A generative feature can be built on a provider’s model and your documentation. A machine learning model needs your history — enough of it, labelled well enough, representative enough of the cases you care about. We look at that first, because it decides whether the project is worth starting."],problems:{eyebrow:"Where ML projects start",heading:"The problems machine learning is bought to solve",intro:"Each of these is a pattern-recognition problem hiding inside an operational one.",items:[{title:"Decisions are being made on intuition at scale",body:"Which lead to call first, which order to inspect, which application to fast-track. Experienced staff are often good at this — but they cannot do it for fifty thousand records a week, and their reasoning leaves when they do."},{title:"Problems are found after they cost money",body:"A failing component, an unusual transaction, a customer who stopped logging in weeks ago. The signal was in the data the whole time; nothing was watching for it."},{title:"Everyone sees the same thing",body:"A catalogue, a course list or a content library presented identically to every user, when behaviour data could put the relevant items first."},{title:"Documents arrive faster than they can be sorted",body:"Scans, forms, emails and attachments that a person opens, identifies and files. Classification is one of the most reliable places to apply ML, because the task is narrow and the labels already exist in your archive."},{title:"A model exists but nothing uses it",body:"A notebook with promising numbers that never reached production. Getting a model into an application — served, versioned, monitored, retrainable — is engineering work that data science alone does not cover."}]},useCases:{eyebrow:"What it is used for",heading:"Applications we build with machine learning",intro:"The list below is limited to task types we can support end to end. Where a use case needs data you do not have, we say so during assessment.",items:[{title:"Prediction and forecasting",body:"Estimating a future value or likelihood from historical patterns: demand, workload, renewal probability, expected duration. Useful when the estimate informs a decision rather than replaces it."},{title:"Classification and scoring",body:"Assigning a category or a score to a record — priority, risk band, likely outcome — so downstream routing and triage can happen automatically for the clear cases."},{title:"Recommendation systems",body:"Ranking items for a specific user from behavioural signals: what they viewed, bought, completed or skipped. Includes handling the cold-start problem for new users and new items."},{title:"Anomaly and outlier detection",body:"Learning what normal looks like in your data and flagging what does not fit — unusual transactions, sensor readings, usage spikes or access patterns — for a human to review."},{title:"Document and text classification",body:"Sorting incoming documents, tickets and messages into the right type, queue or language, and extracting the structured fields that follow from the type."},{title:"Segmentation and clustering",body:"Grouping customers, products or behaviour into segments discovered from the data rather than assumed in advance, then making those segments usable in your tools."}]},capabilities:{eyebrow:"What the work involves",heading:"Machine learning capabilities we deliver",intro:"Most of a successful ML project is data work and integration. The modelling is usually the smallest part of the timeline.",groups:[{title:"Data assessment and preparation",body:"The stage that determines whether anything else is possible, and the one most often skipped.",items:["Inventory of available data, its history, coverage and gaps","Quality review: missing values, duplicates, inconsistent categories, drift over time","Label availability assessment, and a labelling plan where labels do not exist","Feature engineering from raw operational records","Reproducible data pipelines rather than one-off scripts"]},{title:"Model development",body:"Starting simple on purpose: a baseline you can beat is worth more than a complex model you cannot explain.",items:['A simple baseline first, to establish what "better" has to mean',"Classical models where they suit the task and the data volume","Deep learning only where the problem and the dataset justify it","Class imbalance, sampling and validation strategy handled explicitly","Model and dataset versioning so a result can be reproduced"]},{title:"Evaluation",body:"Measured against a held-out set with metrics chosen for the decision being made, not for how good they look.",items:["Metric selection tied to the cost of each kind of mistake","Held-out and time-based validation to avoid optimistic results","Error analysis on the cases the model gets wrong","Comparison against the current manual process as the real benchmark","Fairness and bias review where decisions affect people"]},{title:"Integration into applications",body:"A model becomes useful at the moment it appears inside a screen someone already uses.",items:["Model serving behind an API, with versioning and rollback","Batch scoring pipelines where real-time inference is unnecessary","Predictions surfaced inside web, mobile and internal tools","Confidence shown to the user, with uncertain cases routed to a person","Feedback capture, so corrections become future training data"]},{title:"Monitoring and retraining",body:"Models decay as the world moves. Planning for that is part of the delivery.",items:["Input distribution monitoring to detect drift","Live performance tracking against outcomes once they are known","Alerting when accuracy or data quality degrades","A defined retraining cadence and the pipeline to execute it","Documented behaviour when the model is unavailable"]},{title:"Working with generative AI",body:"The two approaches often belong in the same product, doing different jobs.",items:["Classical models for scoring, ranking and detection","Generative models for language, summarisation and drafting","Model output used as structured input to an assistant or workflow","Shared data pipelines and monitoring across both","A clear boundary so each is judged by its own measures"]}]},approach:{eyebrow:"How we work",heading:"Our approach to machine learning projects",intro:"The discipline here is refusing to promise a number before the data has been seen — and designing so that a wrong prediction is survivable.",points:["Data assessment comes before any modelling proposal, and it can end with a recommendation not to proceed.","A simple baseline is built first, so every later increase in complexity has to justify itself against a measurable benchmark.","The metric is chosen from the cost of each error type: a missed anomaly and a false alarm rarely cost the same thing.","Validation is designed against the way the data actually arrives — time-ordered where the future must not leak into training.","Predictions are delivered with confidence attached, and low-confidence cases go to a person by design.","Data preparation, training and evaluation run as reproducible pipelines, so a result can be recreated months later."]},process:{eyebrow:"Assessment through operation",heading:"How a machine learning project runs",intro:"The first stage is separable and often the only one worth committing to at the start.",steps:[{title:"Discovery and data assessment",body:"We look at the decision being made today and at the data available to inform it, then give an honest read on feasibility.",points:["The operational decision, its frequency, and the cost of getting it wrong","Data inventory: volume, history, coverage, quality and labels",'Feasibility assessment with a clear "not yet" where that applies',"The success measure and the benchmark it must beat","A written recommendation with scope and indicative effort"]},{title:"Data engineering and feature design",body:"Getting from operational records to a training set is usually the longest stage, and the one that decides model quality.",points:["Reproducible extraction and cleaning pipelines","Feature engineering with the business meaning documented","Labelling workflow where labels must be created","Train, validation and test splits designed against real arrival patterns","Data documentation so a future team understands the inputs"]},{title:"Modelling and evaluation",body:"Baseline first, then improvements that must demonstrate themselves on held-out data.",points:["Baseline model and benchmark against the current process","Iterative model development with tracked experiments","Evaluation on held-out and time-based splits","Error analysis and, where relevant, fairness review","A written result including the cases the model handles badly"]},{title:"Integration and quality assurance",body:"The model is wrapped in ordinary software: an API, a schema, a fallback and tests.",points:["Serving API with versioning, timeouts and a defined fallback","Integration into the application or internal tool that uses it","Interface design for confidence, overrides and human review","Automated tests around the serving path and input validation","Shadow running against live traffic before it influences decisions"]},{title:"Deployment, monitoring and retraining",body:"Launch starts the measurement period. Without monitoring, a model quietly gets worse and nobody notices.",points:["Phased rollout, often advisory-only before it becomes automatic","Drift and performance monitoring with alerting","Feedback loop capturing human corrections","Scheduled retraining with the same reproducible pipeline","Ongoing support arrangement for tuning and incidents"]}]},integration:{eyebrow:"Integration",heading:"Getting predictions to where decisions are made",intro:"A prediction that lives in a dashboard nobody opens changes nothing. Integration is scoped as part of every project.",points:["Real-time inference behind an API for interactive screens, or scheduled batch scoring where latency does not matter.","Predictions written back into the systems your team already works in — CRM records, queues, internal tools and dashboards.","Confidence surfaced alongside every prediction, with thresholds that route uncertain cases to a person.","An override path so staff can correct the model, and a record of when they do.","Deployment into your own cloud accounts, with your data staying inside your infrastructure boundary.","A documented fallback rule for when the model or its serving layer is unavailable."]},limitations:{eyebrow:"Honest limits",heading:"What machine learning can and cannot promise",intro:"Feasibility here is a property of your data, not of our engineering. These limits are stated before a project starts, not after.",points:["Model quality is bounded by the data available. Thin history, missing labels or unrepresentative records cap what is achievable, and no modelling technique repairs that.","We do not quote an accuracy figure before assessing your data and building a baseline — any number offered earlier would be guesswork.","A model trained on the past assumes the future resembles it. Market shifts, process changes and new product lines degrade performance until retraining.","Rare events are hard: if something happens in one record in fifty thousand, detecting it reliably needs either far more history or a different framing of the problem.","Correlation in training data is not causation. A model can predict an outcome without telling you how to change it.","Some model types are difficult to explain. Where a decision must be justified to a customer or regulator, we favour models that can be.","We do not promise a business outcome — a revenue increase, a churn reduction or a cost saving. We measure model performance against a benchmark and let you judge the operational value."],oversight:{title:"Human oversight we design in",points:["Confidence thresholds, with anything below them routed to a person","An advisory-first rollout, where staff see the prediction before it automates anything","Override controls, and a record of every override for later analysis","Regular review of the cases the model gets wrong","A named owner for model performance after handover"]},note:"If the data assessment shows the project is not yet feasible, we will tell you that and explain what would have to change — usually more history, better labels, or a narrower problem. That is a cheaper outcome than a model nobody can trust."},engagement:{eyebrow:"Working together",heading:"Engagement options for machine learning",intro:"Nearly every client starts with the assessment, because nothing after it can be priced honestly without it.",options:[{name:"Data assessment",body:"A fixed-scope review of your data and the decision you want to support, delivered as a written feasibility report with options and indicative effort.",bestFor:"Best as a first step, and it stands alone."},{name:"Model build and integration",body:"Data pipelines, model development, evaluation, serving and integration into the application or tool that will use the output.",bestFor:"Best once the assessment shows the data supports it."},{name:"Model operations",body:"Monthly capacity for monitoring, drift response, retraining runs, pipeline maintenance and incremental improvement.",bestFor:"Best for models already influencing real decisions."}]},security:{eyebrow:"Security and privacy",heading:"Handling training data responsibly",intro:"Training data is usually the most sensitive data a company has, because it is historical and complete. These are the practices we apply.",points:["Data minimisation: only the fields the model actually needs leave their source system","Pseudonymisation or removal of direct identifiers where the task does not require them","Training environments with access limited to the named people on the project","Encrypted storage and transport for datasets and model artefacts","Deployment into your own cloud accounts where you prefer data not to move","Documented data lineage: where each dataset came from and what it was used for","Deletion of working copies at the end of an engagement, on request","Review of features that could act as proxies for protected characteristics"],note:"We hold no certification and offer no warranty of security. Where training data is regulated — health, financial or personal data under a specific regime — raise it during the assessment so the handling requirements, and any independent review, are scoped into the work."},faqs:[{question:"How much data do we need?",answer:"It depends far more on the problem than on a single threshold. A document classifier with clear categories can work from a few hundred labelled examples per class; predicting a rare event needs orders of magnitude more. The assessment answers this for your case specifically, and it is a genuine question rather than a formality."},{question:"What if our data is messy?",answer:"Most is. Missing values, inconsistent categories and duplicated records are normal and largely fixable in the data pipeline. What is not fixable is data that never recorded the thing you want to predict, or history so short that no pattern is visible yet."},{question:"How accurate will the model be?",answer:"We will not answer that before seeing your data and building a baseline, and we would be sceptical of anyone who does. What we commit to is a measurable benchmark — usually the current manual process — and honest reporting of performance against it, including the cases the model handles badly."},{question:"Is this the same as adding ChatGPT-style AI?",answer:"No. Generative models produce language from broad pre-training; these models learn patterns from your specific history to score, rank or classify. They often belong in the same product doing different jobs, which is covered on our AI development page."},{question:"Who owns the model and the data?",answer:"You do. Training data stays yours, model artefacts and pipelines are delivered into your repository and cloud accounts, and the work is documented so another team could pick it up."},{question:"What happens when the model gets worse over time?",answer:"It will, and we plan for it. Monitoring watches for drift in the inputs and for performance against outcomes once they are known, with alerting when either degrades. Retraining runs on the same reproducible pipeline that produced the original model."}],markets:{title:"Where our machine learning work is deployed",intro:"A machine learning project depends far more on the data a client can actually share than on where either party sits, so the market pages below deal mainly with how sample data is transferred, held and deleted during a remote engagement."},related:[{path:"/services/ai-development",label:"AI Development",blurb:"The wider AI practice: assistants, generative integrations, retrieval and structured AI workflows."},{path:"/services/ai-automation-integration",label:"AI Automation & Integration",blurb:"Turning a prediction into an action inside your existing systems, with approvals and audit trails."},{path:"/services/conversational-ai-development",label:"Conversational AI Development",blurb:"Where model output needs to be explained to a user in conversation rather than shown as a score."},{path:"/services/web-application-development",label:"Web Application Development",blurb:"The dashboards and internal tools that make predictions visible to the people who act on them."},{path:"/services/saas-development",label:"SaaS Development",blurb:"Multi-tenant products where per-customer models and usage data need careful separation."},{path:"/services/custom-software-development",label:"Custom Software Development",blurb:"The application layer a model has to live inside to be worth anything."}],cta:{title:"Start with your data, not with a model",body:"Tell us what decision you want to support and what history you hold. Get an indicative estimate, talk it through with our AI consultation agent, or contact the team."}},d=()=>e.jsx(t,{content:a(n)});export{d as default};
